package com.cenedu.backend.ai.problem.render;
import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.SemanticResolvedValue; import java.util.*;
public final class PlaneGeometrySvgRenderer { public String render(PlaneGeometryDiagramSpecV1 s){return render(s,Map.of());} public String render(PlaneGeometryDiagramSpecV1 s,Map<String,SemanticResolvedValue> values){int p=s.viewport().padding();StringBuilder b=new StringBuilder("<rect x=\"").append(p).append("\" y=\"").append(p).append("\" width=\"").append(s.viewport().width()-2*p).append("\" height=\"").append(s.viewport().height()-2*p).append("\" fill=\"none\" stroke=\"#000000\"/>");Map<String,int[]> points=new HashMap<>();for(var point:s.points()){int x=p+20,y=p+20;points.put(point.pointKey(),new int[]{x,y});b.append("<circle cx=\"").append(x).append("\" cy=\"").append(y).append("\" r=\"3\" fill=\"#000000\"/>");}for(var seg:s.segments()){int[] a=points.get(seg.startPointKey()),c=points.get(seg.endPointKey());if(a!=null&&c!=null)b.append("<line x1=\"").append(a[0]).append("\" y1=\"").append(a[1]).append("\" x2=\"").append(c[0]).append("\" y2=\"").append(c[1]).append("\" stroke=\"#000000\"/>");}for(var circle:s.circles()){int[] c=points.get(circle.centerPointKey());if(c!=null)b.append("<circle cx=\"").append(c[0]).append("\" cy=\"").append(c[1]).append("\" r=\"20\" fill=\"none\" stroke=\"#000000\"/>");}return b.toString();} }
